CREATE OR REPLACE FUNCTION public.finance_complete_google_identity_trigger_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old_verified boolean := false;
  v_new_verified boolean := false;
  v_old_email text;
  v_new_email text;
  v_result jsonb;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    v_old_verified := old.provider = 'google'
      and lower(coalesce(old.identity_data ->> 'email_verified', 'false'))
          in ('true', '1');
    v_old_email := lower(pg_catalog.btrim(coalesce(
      old.identity_data ->> 'email',
      ''
    )));
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    v_new_verified := new.provider = 'google'
      and lower(coalesce(new.identity_data ->> 'email_verified', 'false'))
          in ('true', '1');
    v_new_email := lower(pg_catalog.btrim(coalesce(
      new.identity_data ->> 'email',
      ''
    )));
  end if;

  if tg_op = 'DELETE' then
    if v_old_verified then
      perform private.finance_revoke_invalid_google_identity_v2(
        old.user_id,
        v_old_email,
        'Google 身分已刪除；帳號已停止使用並等待管理者檢查。'
      );
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' and v_old_verified and not v_new_verified then
    perform private.finance_revoke_invalid_google_identity_v2(
      old.user_id,
      v_old_email,
      'Google 身分已取消驗證；帳號已停止使用並等待管理者檢查。'
    );
    return new;
  end if;

  if v_new_verified then
    v_result := private.finance_complete_verified_google_account_link_v2(
      new.user_id,
      v_new_email,
      null
    );

    if tg_op = 'UPDATE'
       and v_old_verified
       and v_old_email <> v_new_email
       and (
         coalesce((v_result ->> 'ok')::boolean, false) is not true
         or coalesce(v_result ->> 'status', '') <> 'bound'
       ) then
      raise exception
        'Google 主信箱換綁未完整完成，身分變更已整筆回滾。'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_guard_google_identity_lifecycle_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old_verified boolean;
  v_new_verified boolean := false;
  v_old_email text;
  v_new_email text;
  v_finance public.finance_users%rowtype;
begin
  v_old_verified := old.provider = 'google'
    and lower(coalesce(old.identity_data ->> 'email_verified', 'false'))
        in ('true', '1');
  v_old_email := lower(pg_catalog.btrim(coalesce(
    old.identity_data ->> 'email',
    ''
  )));

  if not v_old_verified then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    v_new_verified := new.provider = 'google'
      and lower(coalesce(new.identity_data ->> 'email_verified', 'false'))
          in ('true', '1');
    v_new_email := lower(pg_catalog.btrim(coalesce(
      new.identity_data ->> 'email',
      ''
    )));

    if v_new_verified and v_new_email = v_old_email then
      return new;
    end if;
  end if;

  select fu.*
  into v_finance
  from public.finance_users fu
  where fu.active = true
    and fu.auth_user_id = old.user_id
    and lower(pg_catalog.btrim(fu.email)) = v_old_email
    and fu.google_link_status in ('bound', 'pending_rebind')
  order by fu.created_at asc, fu.id asc
  limit 1
  for update;

  if v_finance.id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' and v_new_verified then
    if v_finance.google_link_status <> 'pending_rebind'
       or lower(pg_catalog.btrim(coalesce(
         v_finance.pending_login_email,
         ''
       ))) <> v_new_email then
      raise exception
        'Google 主信箱尚未由人員管理核准換綁，已取消這次身分變更。'
        using errcode = '42501';
    end if;
    return new;
  end if;

  -- Identity revocation must never be vetoed by workflow responsibility.
  -- The AFTER trigger disables access and approval capability immediately;
  -- HR can then complete the normal reassignment/offboarding workflow without
  -- leaving a stolen or terminated Google identity usable in the meantime.
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_edoc_enqueue_member_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    perform private.finance_edoc_touch_member_v1(new.tenant_id, new.id);
  elsif new.member_revision is distinct from old.member_revision then
    perform private.finance_edoc_touch_member_v1(new.tenant_id, new.id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_bump_member_revision_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    new.member_revision := 1;
  elsif new is distinct from old then
    if old.member_revision = 9223372036854775807 then
      raise exception 'Member revision exhausted for finance user %', old.id
        using errcode = '54000';
    end if;
    new.member_revision := old.member_revision + 1;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_guard_google_link_control_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_authorized boolean := false;
  v_verified_email text;
  v_lock_email text;
begin
  new.email := private.finance_google_normalized_email_v2(new.email);
  new.pending_login_email := nullif(
    private.finance_google_normalized_email_v2(new.pending_login_email),
    ''
  );
  new.google_link_revision := coalesce(new.google_link_revision, 0);

  if new.email = ''
     or new.email !~ '^[^@[:space:]]+@suiyuecare[.]com$' then
    raise exception 'Finance login email must be an exact company Google email'
      using errcode = '22023';
  end if;

  if tg_op = 'INSERT' then
    if new.auth_user_id is null then
      new.google_link_status := 'pending_first_login';
      new.pending_login_email := null;
      new.google_login_verified_at := null;
      new.google_link_status_detail := coalesce(
        nullif(new.google_link_status_detail, ''),
        '等待本人首次使用公司 Google 主帳號登入。'
      );
    else
      v_verified_email := public.finance_verified_google_email(new.auth_user_id);
      if v_verified_email = new.email then
        new.google_link_status := 'bound';
        new.pending_login_email := null;
        new.google_login_verified_at := coalesce(new.google_login_verified_at, now());
        new.google_last_linked_at := coalesce(new.google_last_linked_at, now());
      else
        new.google_link_status := 'conflict';
        new.pending_login_email := null;
        new.google_login_verified_at := null;
      end if;
    end if;
  else
    select exists (
      select 1
      from private.finance_google_link_mutation_authorizations_v2 authz
      where authz.backend_pid = pg_catalog.pg_backend_pid()
        and authz.transaction_id = pg_catalog.txid_current()
        and authz.tenant_id = old.tenant_id
        and authz.finance_user_id = old.id
        and authz.old_email = lower(btrim(old.email))
        and authz.new_email = lower(btrim(new.email))
        and authz.old_auth_user_id is not distinct from old.auth_user_id
        and authz.new_auth_user_id is not distinct from new.auth_user_id
        and authz.target_revision = new.google_link_revision
        and authz.created_at >= clock_timestamp() - interval '5 minutes'
    ) into v_authorized;

    v_verified_email := public.finance_verified_google_email(new.auth_user_id);

    if (
      old.email is distinct from new.email
      or old.auth_user_id is distinct from new.auth_user_id
      or old.google_link_status is distinct from new.google_link_status
      or old.pending_login_email is distinct from new.pending_login_email
      or old.google_link_revision is distinct from new.google_link_revision
      or old.google_link_requested_at is distinct from new.google_link_requested_at
      or old.google_link_requested_by is distinct from new.google_link_requested_by
      or old.google_link_status_detail is distinct from new.google_link_status_detail
      or old.google_last_linked_at is distinct from new.google_last_linked_at
    ) and not v_authorized then
      raise exception
        'Google login linkage fields can only be changed through the V2 transactional contract'
        using errcode = '42501';
    end if;

    if old.tenant_id is distinct from new.tenant_id
       and (
         old.auth_user_id is not null
         or old.google_link_status in ('bound', 'pending_rebind')
       ) then
      raise exception 'Move the Finance person with the formal tenant workflow before changing Google linkage'
        using errcode = '23514';
    end if;
  end if;

  v_lock_email := coalesce(new.pending_login_email, new.email);
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('finance-google-email:' || v_lock_email, 20260804)
  );

  if new.active = true and exists (
    select 1
    from public.finance_users other
    where other.id <> new.id
      and other.active = true
      and (
        lower(btrim(other.email)) = new.email
        or lower(btrim(coalesce(other.pending_login_email, ''))) = new.email
        or (
          new.pending_login_email is not null
          and (
            lower(btrim(other.email)) = new.pending_login_email
            or lower(btrim(coalesce(other.pending_login_email, ''))) = new.pending_login_email
          )
        )
      )
  ) then
    raise exception 'The requested Google login email is already reserved by another Finance user'
      using errcode = '23505';
  end if;

  if new.google_link_status = 'bound' then
    if new.auth_user_id is null
       or new.pending_login_email is not null
       or public.finance_verified_google_email(new.auth_user_id) <> new.email then
      raise exception 'A bound Finance account requires one exact-email verified Google identity'
        using errcode = '23514';
    end if;
  elsif new.google_link_status = 'pending_rebind' then
    if new.auth_user_id is null or new.pending_login_email is null then
      raise exception 'A pending rebind must preserve the current binding and reserve a replacement email'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_guard_hr_personnel_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role text := coalesce(public.current_finance_role(), '');
  v_privileged_roles text[] := array[
    'ceo',
    'admin_director',
    'accountant',
    'cashier',
    'hr',
    'external_audit',
    'board',
    'shareholder'
  ];
begin
  if auth.uid() is null or v_role <> 'hr' then
    return new;
  end if;

  if new.tenant_id is distinct from public.current_tenant_id() then
    raise exception 'HR may manage personnel only inside the current tenant'
      using errcode = '42501';
  end if;

  if new.role = any(v_privileged_roles)
     or (tg_op = 'UPDATE' and old.role = any(v_privileged_roles)) then
    raise exception 'HR cannot assign or modify Finance control-plane roles'
      using errcode = '42501';
  end if;

  if tg_op = 'UPDATE'
     and (
       new.auth_user_id is distinct from old.auth_user_id
       or lower(new.email) is distinct from lower(old.email)
     )
     and (
       old.auth_user_id is not null
       or new.auth_user_id is not null
     )
     and (
       new.auth_user_id is null
       or not exists (
         select 1
         from auth.identities identity
         where identity.user_id = new.auth_user_id
           and identity.provider = 'google'
           and lower(coalesce(identity.identity_data ->> 'email', '')) =
               lower(new.email)
           and lower(coalesce(
             identity.identity_data ->> 'email_verified',
             'false'
           )) in ('true', '1')
       )
     ) then
    raise exception 'HR may bind only an exact-email, verified Google identity'
      using errcode = '42501';
  end if;

  if tg_op = 'INSERT' and new.auth_user_id is not null then
    raise exception 'New HR-created personnel must claim Google identity by first login'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

