CREATE OR REPLACE FUNCTION public.normalize_invoice_identifier_type_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.invoice_identifier_type := public.normalize_invoice_identifier_type(new.invoice_identifier_type);
  return new;
