CREATE OR REPLACE FUNCTION private.finance_bump_approval_row_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    -- Never trust a caller-supplied initial version, including direct table
    -- INSERTs allowed by RLS.  Every new source row starts at version 1.
    new.row_version := 1;
    return new;
  end if;

  if old.row_version >= 9223372036854775807::bigint then
    raise exception 'Approval source row version is exhausted'
      using errcode = '54000';
  end if;

  new.row_version := old.row_version + 1;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_enqueue_current_approval_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_row jsonb := to_jsonb(new);
  v_tenant_text text;
  v_tenant_id uuid;
  v_environment text;
  v_source_status text;
  v_source_id text;
  v_source_group_id text;
  v_source_no text;
  v_source_label text;
  v_step_number integer;
  v_steps jsonb;
  v_current_step jsonb;
  v_role_key text;
  v_role_label text;
  v_recipient_id text;
  v_recipient_name text;
  v_recipient_email text;
  v_assignment_key text;
  v_generation integer;
  v_event_id text;
  v_inserted_count integer := 0;
  v_group_still_pending boolean := false;
begin
  v_source_id := nullif(trim(v_row ->> 'id'), '');
  v_tenant_text := nullif(trim(v_row ->> 'tenant_id'), '');
  v_environment := lower(nullif(trim(v_row ->> 'data_environment'), ''));

  -- Tenant and environment are authorization boundaries. Never infer either
  -- one for a notification, even if a legacy default exists on the table.
  if v_source_id is null or v_tenant_text is null or v_environment is null then
    return new;
  end if;

  begin
    v_tenant_id := v_tenant_text::uuid;
  exception
    when invalid_text_representation then
      return new;
  end;

  v_source_group_id := coalesce(nullif(trim(v_row ->> 'batch_id'), ''), v_source_id);
  v_source_status := lower(coalesce(
    nullif(v_row ->> 'approval_status', ''),
    nullif(v_row ->> 'status', ''),
    ''
  ));
  v_step_number := case
    when coalesce(v_row ->> 'approval_step', v_row ->> 'step', '') ~ '^[0-9]+$'
      then coalesce(v_row ->> 'approval_step', v_row ->> 'step')::integer
    else 0
  end;
  v_steps := coalesce(v_row -> 'steps', '[]'::jsonb);
  v_current_step := case
    when jsonb_typeof(v_steps) = 'array'
      and v_step_number between 1 and jsonb_array_length(v_steps)
      then v_steps -> (v_step_number - 1)
    else null
  end;

  if v_environment <> 'production'
    or v_source_status not like 'pending%'
    or v_current_step is null
    or nullif(trim(coalesce(v_current_step ->> 'a', '')), '') is not null then
    if tg_table_name in ('invoices', 'bills') and v_environment = 'production' then
      execute format(
        'select exists (
           select 1
           from public.%I r
           where coalesce(nullif(r.batch_id::text, ''''), r.id::text) = $1
             and r.id::text <> $2
             and r.tenant_id = $3
             and r.data_environment = $4
             and lower(coalesce(nullif(r.approval_status, ''''), r.status, '''')) like ''pending%%''
         )',
        tg_table_name
      )
      into v_group_still_pending
      using v_source_group_id, v_source_id, v_tenant_id, v_environment;
    end if;

    if not v_group_still_pending then
      delete from private.approval_notification_assignment_state
      where tenant_id = v_tenant_id
        and data_environment = v_environment
        and source_table = tg_table_name
        and source_group_id = v_source_group_id;
    end if;
    return new;
  end if;

  v_recipient_id := nullif(trim(coalesce(v_current_step ->> 'uid', '')), '');
  if v_recipient_id is null then
    return new;
  end if;

  select u.name, lower(trim(u.email))
  into v_recipient_name, v_recipient_email
  from public.finance_users u
  where u.id = v_recipient_id
    and u.tenant_id = v_tenant_id
    and u.active is not false
  limit 1;

  if v_recipient_email is null
    or v_recipient_email !~* '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then
    return new;
  end if;

  v_role_key := coalesce(nullif(v_current_step ->> 'rk', ''), 'approver');
  v_role_label := coalesce(
    nullif(v_current_step ->> 'r', ''),
    nullif(v_current_step ->> 'label', ''),
    '簽核人'
  );
  v_assignment_key := concat_ws('|', v_step_number::text, v_recipient_id, v_role_key);

  insert into private.approval_notification_assignment_state (
    tenant_id,
    data_environment,
    source_table,
    source_group_id,
    source_record_id,
    assignment_key,
    assignment_generation,
    recipient_finance_user_id,
    updated_at
  ) values (
    v_tenant_id,
    v_environment,
    tg_table_name,
    v_source_group_id,
    v_source_id,
    v_assignment_key,
    1,
    v_recipient_id,
    now()
  )
  on conflict (tenant_id, data_environment, source_table, source_group_id)
  do update set
    source_record_id = excluded.source_record_id,
    assignment_key = excluded.assignment_key,
    assignment_generation = private.approval_notification_assignment_state.assignment_generation + 1,
    recipient_finance_user_id = excluded.recipient_finance_user_id,
    notification_event_id = null,
    updated_at = now()
  where private.approval_notification_assignment_state.assignment_key
    is distinct from excluded.assignment_key
  returning assignment_generation into v_generation;

  if v_generation is null then
    return new;
  end if;

  v_source_no := coalesce(
    nullif(trim(v_row ->> 'no'), ''),
    nullif(trim(v_row ->> 'request_no'), ''),
    v_source_id
  );
  v_source_label := case
    when tg_table_name = 'invoices' then '發票申請'
    when tg_table_name = 'bills' then '繳費單申請'
    when coalesce(v_row ->> 'type', '') = 'shareholder_transaction' then '股東／公司往來申請'
    else '支出申請'
  end;
  v_event_id := 'nde_approval_' || substr(md5(concat_ws(
    '|',
    v_tenant_id::text,
    v_environment,
    tg_table_name,
    v_source_group_id,
    v_assignment_key,
    v_generation::text
  )), 1, 28);

  insert into public.notification_delivery_events (
    id,
    event_type,
    title,
    body,
    request_id,
    channels,
    status,
    payload,
    data_environment,
    tenant_id,
    next_retry_at,
    max_attempts
  ) values (
    v_event_id,
    'approval_task_assigned',
    '待您簽核｜' || v_source_no || '｜' || v_role_label,
    coalesce(nullif(v_recipient_name, ''), '同仁')
      || '您好，您已收到一筆新的' || v_source_label || '簽核待辦，目前關卡為「'
      || v_role_label || '」。請儘速登入歲悅財務系統完成簽核，以利流程進入下一關。',
    v_source_no,
    array['email']::text[],
    'pending',
    jsonb_build_object(
      'template', 'approval_task_assigned_v2',
      'direct_link_version', 2,
      'recipient_emails', jsonb_build_array(v_recipient_email),
      'recipient_name', coalesce(v_recipient_name, ''),
      'recipient_finance_user_id', v_recipient_id,
      'source_table', tg_table_name,
      'source_id', v_source_id,
      'source_group_id', v_source_group_id,
      'source_no', v_source_no,
      'source_label', v_source_label,
      'tenant_id', v_tenant_id::text,
      'data_environment', v_environment,
      'entity_id', coalesce(v_row ->> 'entity_id', ''),
      'applicant', coalesce(v_row ->> 'applicant', ''),
      'amount', coalesce(v_row ->> 'amount', v_row ->> 'total', ''),
      'approval_step', v_step_number,
      'approval_role_key', v_role_key,
      'approval_role_label', v_role_label,
      'assignment_generation', v_generation,
      'app_url', 'https://finance.suiyuecare.com/'
    ),
    v_environment,
    v_tenant_id,
    now(),
    20
  )
  on conflict (id) do nothing;

  get diagnostics v_inserted_count = row_count;
  if v_inserted_count = 0 and not exists (
    select 1
    from public.notification_delivery_events existing
    where existing.id = v_event_id
      and existing.event_type = 'approval_task_assigned'
      and existing.tenant_id = v_tenant_id
      and existing.data_environment = v_environment
      and existing.request_id = v_source_no
      and existing.payload ->> 'source_table' = tg_table_name
      and existing.payload ->> 'source_id' = v_source_id
      and existing.payload ->> 'source_group_id' = v_source_group_id
      and existing.payload ->> 'source_no' = v_source_no
      and existing.payload ->> 'recipient_finance_user_id' = v_recipient_id
      and existing.payload -> 'recipient_emails' = jsonb_build_array(v_recipient_email)
  ) then
    raise exception using
      errcode = 'PNA01',
      message = format(
        'Reserved approval notification id collision for %s',
        v_event_id
      ),
      hint = 'Do not retry the business action until the conflicting event has been investigated.';
  end if;

  update private.approval_notification_assignment_state
  set notification_event_id = v_event_id,
      updated_at = now()
  where tenant_id = v_tenant_id
    and data_environment = v_environment
    and source_table = tg_table_name
    and source_group_id = v_source_group_id
    and assignment_generation = v_generation;

  begin
    perform private.finance_wake_notification_worker();
  exception
    when others then
      raise warning 'Approval email queued but worker wake failed: %', sqlerrm;
  end;

  return new;
exception
  when sqlstate 'PNA01' then
    -- A deterministic id collision is a security incident. Never let the
    -- trigger's best-effort fallback hide it or silently lose the email.
    raise;
  when others then
    raise warning 'Approval email enqueue skipped for %.%: %', tg_table_name, coalesce(v_source_id, '?'), sqlerrm;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.neutralize_premature_invoice_posting_flags()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  mode text := coalesce(private.finance_audit_posting_guard_mode(), 'observe');
  premature_transition boolean;
begin
  if mode = 'off'
     or coalesce(new.data_environment, 'production') <> 'production'
     or new.voided_at is not null
     or private.finance_invoice_fully_approved(new.steps) then
    return new;
  end if;

  premature_transition :=
    (coalesce(old.revenue_posted, false) = false and coalesce(new.revenue_posted, false) = true)
    or (old.revenue_posted_at is null and new.revenue_posted_at is not null)
    or (
      old.posting_locked_at is null and new.posting_locked_at is not null
      and coalesce(new.revenue_posted, false) = true
    );

  if premature_transition then
    perform private.record_finance_guard_event(
      'invoice_premature_flag_neutralized:' || new.id,
      'invoice_premature_flag_neutralized', mode, 'invoice', new.id, new.no,
      jsonb_build_object(
        'approval_status', new.approval_status,
        'legacy_revenue_posted', new.revenue_posted,
        'legacy_revenue_posted_at', new.revenue_posted_at
      ), new.tenant_id
    );

    new.revenue_posted := old.revenue_posted;
    new.revenue_posted_at := old.revenue_posted_at;
    if old.posting_locked_at is null then
      new.posting_locked_at := null;
    end if;
    new.revenue_posting_state := case
      when coalesce(old.revenue_posted, false) then old.revenue_posting_state
      else 'deferred'
    end;
    new.revenue_posting_error := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.post_invoice_revenue_after_final_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  mode text := coalesce(private.finance_audit_posting_guard_mode(), 'observe');
begin
  if mode = 'off'
     or coalesce(new.data_environment, 'production') <> 'production'
     or new.voided_at is not null
     or coalesce(new.revenue_posted, false) then
    return new;
  end if;

  if private.finance_invoice_fully_approved(new.steps)
     and not private.finance_invoice_fully_approved(old.steps) then
    begin
      perform private.post_invoice_revenue_v2_internal(new.id, true);
    exception when others then
      perform private.record_finance_guard_event(
        'invoice_final_posting_failed:' || new.id,
        'invoice_final_posting_failed', mode, 'invoice', new.id, new.no,
        jsonb_build_object('error', sqlerrm, 'sqlstate', sqlstate), new.tenant_id
      );
      update public.invoices
      set revenue_posting_state = 'pending_accounting_review',
          revenue_posting_error = left(sqlerrm, 1000),
          updated_at = now()
      where id = new.id;
    end;
  end if;

  return new;
end;
$function$

