CREATE OR REPLACE FUNCTION private.finance_claim_attachment_metadata_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_document jsonb := pg_catalog.to_jsonb(new);
  v_old_document jsonb := '{}'::jsonb;
  v_tenant_id uuid;
  v_record_type text;
  v_environment text;
  v_primary_identifier text;
  v_batch_identifier text;
  v_batch_display_no text;
  v_note jsonb;
  v_actor_finance_user_id text;
  v_actor_auth_user_id uuid;
begin
  if tg_op = 'UPDATE' then
    v_old_document := pg_catalog.to_jsonb(old);
  end if;

  v_tenant_id := nullif(v_document ->> 'tenant_id', '')::uuid;
  v_environment := coalesce(
    nullif(v_document ->> 'data_environment', ''),
    'production'
  );

  -- Staged metadata can only be promoted by the same verified signed-in user
  -- who uploaded the corresponding Storage object.  Document actor fields are
  -- deliberately not accepted as a substitute for the live OAuth identity.
  v_actor_auth_user_id := auth.uid();
  v_actor_finance_user_id := nullif(
    public.current_finance_user_id(),
    ''
  );

  case tg_table_name
    when 'expense_requests' then
      v_record_type := 'expense_requests';
      v_primary_identifier := coalesce(
        nullif(v_document ->> 'no', ''),
        nullif(v_document ->> 'id', '')
      );
    when 'invoices' then
      v_record_type := 'invoices';
      v_batch_identifier := nullif(v_document ->> 'batch_id', '');
      v_primary_identifier := coalesce(
        v_batch_identifier,
        nullif(v_document ->> 'no', ''),
        nullif(v_document ->> 'id', '')
      );
    when 'bills' then
      v_record_type := 'bills';
      v_batch_identifier := nullif(v_document ->> 'batch_id', '');
      begin
        v_note := coalesce(
          nullif(v_document ->> 'note', '')::jsonb,
          '{}'::jsonb
        );
      exception
        when invalid_text_representation then
          v_note := '{}'::jsonb;
      end;
      v_batch_display_no := coalesce(
        nullif(v_note ->> 'batchNo', ''),
        nullif(v_note ->> 'batch_no', '')
      );
      v_primary_identifier := coalesce(
        v_batch_display_no,
        v_batch_identifier,
        nullif(v_document ->> 'no', ''),
        nullif(v_document ->> 'id', '')
      );
    when 'vouchers' then
      v_record_type := 'vouchers';
      v_primary_identifier := coalesce(
        nullif(v_document ->> 'no', ''),
        nullif(v_document ->> 'id', ''),
        nullif(v_document ->> 'request_id', '')
      );
    else
      return new;
  end case;

  if v_tenant_id is null
     or v_primary_identifier is null then
    return new;
  end if;

  -- Exact path membership replaces provisional record-number equality.  Every
  -- other trust boundary remains mandatory, including the live OAuth actor and
  -- storage.objects.owner_id.  On UPDATE, only newly added paths are eligible;
  -- this prevents a harmless edit from mutating historical attachment rows.
  if v_actor_finance_user_id is not null
     and v_actor_auth_user_id is not null then
    update public.file_attachments attachment
    set
      record_no = v_primary_identifier,
      attachment_state = 'claimed',
      claimed_at = coalesce(
        attachment.claimed_at,
        pg_catalog.clock_timestamp()
      ),
      claim_key = v_record_type || ':' || v_primary_identifier
    from storage.objects object_row,
         public.finance_users uploader
    where attachment.tenant_id = v_tenant_id
      and attachment.bucket_id = 'finance-attachments'
      and attachment.record_type = v_record_type
      and attachment.data_environment = v_environment
      and attachment.attachment_state = 'staged'
      and attachment.uploaded_by = v_actor_finance_user_id
      and private.finance_is_current_document_attachment_path_v3(
        attachment.storage_path,
        v_tenant_id,
        v_record_type,
        v_environment
      )
      and private.finance_json_contains_attachment_path_v2(
        v_document,
        attachment.storage_path
      )
      and (
        tg_op = 'INSERT'
        or not private.finance_json_contains_attachment_path_v2(
          v_old_document,
          attachment.storage_path
        )
      )
      and object_row.bucket_id = attachment.bucket_id
      and object_row.name = attachment.storage_path
      and object_row.owner_id = v_actor_auth_user_id::text
      and uploader.tenant_id = attachment.tenant_id
      and uploader.id = attachment.uploaded_by
      and uploader.auth_user_id = v_actor_auth_user_id;
  end if;

  -- INSERT is strict for every new-format Finance Storage reference.  UPDATE is
  -- strict only for paths absent from OLD, so a historical missing object does
  -- not block unrelated workflow or accounting changes.
  if exists (
    select 1
    from private.finance_attachment_paths_in_document_v2(v_document)
      referenced_path(storage_path)
    where private.finance_is_current_finance_attachment_path_v3(
      referenced_path.storage_path
    )
      and (
        tg_op = 'INSERT'
        or not private.finance_json_contains_attachment_path_v2(
          v_old_document,
          referenced_path.storage_path
        )
      )
      and not exists (
        select 1
        from public.file_attachments attachment
        join storage.objects object_row
          on object_row.bucket_id = attachment.bucket_id
         and object_row.name = attachment.storage_path
        join public.finance_users uploader
          on uploader.tenant_id = attachment.tenant_id
         and uploader.id = attachment.uploaded_by
         and uploader.auth_user_id::text = object_row.owner_id
        where attachment.tenant_id = v_tenant_id
          and attachment.bucket_id = 'finance-attachments'
          and attachment.storage_path = referenced_path.storage_path
          and attachment.record_type = v_record_type
          and attachment.record_no = v_primary_identifier
          and attachment.data_environment = v_environment
          and attachment.attachment_state = 'claimed'
          and attachment.claimed_at is not null
          and attachment.uploaded_by = v_actor_finance_user_id
          and uploader.auth_user_id = v_actor_auth_user_id
      )
  ) then
    raise exception
      '附件尚未依正式單號完成綁定，系統已取消本次寫入，請重新整理後再試'
      using errcode = '55000';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.finance_assert_pending_step_assignees_active()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row jsonb := pg_catalog.to_jsonb(new);
  v_tenant_id uuid;
  v_status text;
  v_steps jsonb;
  v_assignee_id text;
begin
  v_tenant_id := nullif(v_row ->> 'tenant_id', '')::uuid;
  v_status := lower(coalesce(
    nullif(v_row ->> 'approval_status', ''),
    nullif(v_row ->> 'status', ''),
    ''
  ));
  v_steps := coalesce(v_row -> 'steps', '[]'::jsonb);

  if v_tenant_id is null
     or v_status not like 'pending%'
     or pg_catalog.jsonb_typeof(v_steps) <> 'array' then
    return new;
  end if;

  for v_assignee_id in
    select distinct nullif(step_row.step ->> 'uid', '')
    from pg_catalog.jsonb_array_elements(v_steps) step_row(step)
    where coalesce(step_row.step ->> 'a', '') = ''
      and nullif(step_row.step ->> 'uid', '') is not null
    order by 1
  loop
    perform 1
    from public.finance_users finance_user
    where finance_user.tenant_id = v_tenant_id
      and finance_user.id = v_assignee_id
      and finance_user.active is true
    for key share;

    if not found then
      raise exception '待簽人員已停用或不存在，請重新整理主管與簽核設定後再送出'
        using errcode = '23514',
              detail = 'OFFBOARDING_ASSIGNEE_NOT_ACTIVE';
    end if;
  end loop;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_enqueue_current_approval_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_row jsonb := to_jsonb(new);
  v_tenant_text text;
  v_tenant_id uuid;
  v_environment text;
  v_source_status text;
  v_source_id text;
  v_source_group_id text;
  v_source_no text;
  v_source_label text;
  v_step_number integer;
  v_steps jsonb;
  v_current_step jsonb;
  v_role_key text;
  v_role_label text;
  v_recipient_id text;
  v_recipient_name text;
  v_recipient_email text;
  v_assignment_key text;
  v_generation integer;
  v_event_id text;
  v_inserted_count integer := 0;
  v_group_still_pending boolean := false;
begin
  v_source_id := nullif(trim(v_row ->> 'id'), '');
  v_tenant_text := nullif(trim(v_row ->> 'tenant_id'), '');
  v_environment := lower(nullif(trim(v_row ->> 'data_environment'), ''));

  -- Tenant and environment are authorization boundaries. Never infer either
  -- one for a notification, even if a legacy default exists on the table.
  if v_source_id is null or v_tenant_text is null or v_environment is null then
    return new;
  end if;

  begin
    v_tenant_id := v_tenant_text::uuid;
  exception
    when invalid_text_representation then
      return new;
  end;

  v_source_group_id := coalesce(nullif(trim(v_row ->> 'batch_id'), ''), v_source_id);
  v_source_status := lower(coalesce(
    nullif(v_row ->> 'approval_status', ''),
    nullif(v_row ->> 'status', ''),
    ''
  ));
  v_step_number := case
    when coalesce(v_row ->> 'approval_step', v_row ->> 'step', '') ~ '^[0-9]+$'
      then coalesce(v_row ->> 'approval_step', v_row ->> 'step')::integer
    else 0
  end;
  v_steps := coalesce(v_row -> 'steps', '[]'::jsonb);
  v_current_step := case
    when jsonb_typeof(v_steps) = 'array'
      and v_step_number between 1 and jsonb_array_length(v_steps)
      then v_steps -> (v_step_number - 1)
    else null
  end;

  if v_environment <> 'production'
    or v_source_status not like 'pending%'
    or v_current_step is null
    or nullif(trim(coalesce(v_current_step ->> 'a', '')), '') is not null then
    if tg_table_name in ('invoices', 'bills') and v_environment = 'production' then
      execute format(
        'select exists (
           select 1
           from public.%I r
           where coalesce(nullif(r.batch_id::text, ''''), r.id::text) = $1
             and r.id::text <> $2
             and r.tenant_id = $3
             and r.data_environment = $4
             and lower(coalesce(nullif(r.approval_status, ''''), r.status, '''')) like ''pending%%''
         )',
        tg_table_name
      )
      into v_group_still_pending
      using v_source_group_id, v_source_id, v_tenant_id, v_environment;
    end if;

    if not v_group_still_pending then
      delete from private.approval_notification_assignment_state
      where tenant_id = v_tenant_id
        and data_environment = v_environment
        and source_table = tg_table_name
        and source_group_id = v_source_group_id;
    end if;
    return new;
  end if;

  v_recipient_id := nullif(trim(coalesce(v_current_step ->> 'uid', '')), '');
  if v_recipient_id is null then
    return new;
  end if;

  select u.name, lower(trim(u.email))
  into v_recipient_name, v_recipient_email
  from public.finance_users u
  where u.id = v_recipient_id
    and u.tenant_id = v_tenant_id
    and u.active is not false
  limit 1;

  if v_recipient_email is null
    or v_recipient_email !~* '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then
    return new;
  end if;

  v_role_key := coalesce(nullif(v_current_step ->> 'rk', ''), 'approver');
  v_role_label := coalesce(
    nullif(v_current_step ->> 'r', ''),
    nullif(v_current_step ->> 'label', ''),
    '簽核人'
  );
  v_assignment_key := concat_ws('|', v_step_number::text, v_recipient_id, v_role_key);

  insert into private.approval_notification_assignment_state (
    tenant_id,
    data_environment,
    source_table,
    source_group_id,
    source_record_id,
    assignment_key,
    assignment_generation,
    recipient_finance_user_id,
    updated_at
  ) values (
    v_tenant_id,
    v_environment,
    tg_table_name,
    v_source_group_id,
    v_source_id,
    v_assignment_key,
    1,
    v_recipient_id,
    now()
  )
  on conflict (tenant_id, data_environment, source_table, source_group_id)
  do update set
    source_record_id = excluded.source_record_id,
    assignment_key = excluded.assignment_key,
    assignment_generation = private.approval_notification_assignment_state.assignment_generation + 1,
    recipient_finance_user_id = excluded.recipient_finance_user_id,
    notification_event_id = null,
    updated_at = now()
  where private.approval_notification_assignment_state.assignment_key
    is distinct from excluded.assignment_key
  returning assignment_generation into v_generation;

  if v_generation is null then
    return new;
  end if;

  v_source_no := coalesce(
    nullif(trim(v_row ->> 'no'), ''),
    nullif(trim(v_row ->> 'request_no'), ''),
    v_source_id
  );
  v_source_label := case
    when tg_table_name = 'invoices' then '發票申請'
    when tg_table_name = 'bills' then '繳費單申請'
    when coalesce(v_row ->> 'type', '') = 'shareholder_transaction' then '股東／公司往來申請'
    else '支出申請'
  end;
  v_event_id := 'nde_approval_' || substr(md5(concat_ws(
    '|',
    v_tenant_id::text,
    v_environment,
    tg_table_name,
    v_source_group_id,
    v_assignment_key,
    v_generation::text
  )), 1, 28);

  insert into public.notification_delivery_events (
    id,
    event_type,
    title,
    body,
    request_id,
    channels,
    status,
    payload,
    data_environment,
    tenant_id,
    next_retry_at,
    max_attempts
  ) values (
    v_event_id,
    'approval_task_assigned',
    '待您簽核｜' || v_source_no || '｜' || v_role_label,
    coalesce(nullif(v_recipient_name, ''), '同仁')
      || '您好，您已收到一筆新的' || v_source_label || '簽核待辦，目前關卡為「'
      || v_role_label || '」。請儘速登入歲悅財務系統完成簽核，以利流程進入下一關。',
    v_source_no,
    array['email']::text[],
    'pending',
    jsonb_build_object(
      'template', 'approval_task_assigned_v2',
      'direct_link_version', 2,
      'recipient_emails', jsonb_build_array(v_recipient_email),
      'recipient_name', coalesce(v_recipient_name, ''),
      'recipient_finance_user_id', v_recipient_id,
      'source_table', tg_table_name,
      'source_id', v_source_id,
      'source_group_id', v_source_group_id,
      'source_no', v_source_no,
      'source_label', v_source_label,
      'tenant_id', v_tenant_id::text,
      'data_environment', v_environment,
      'entity_id', coalesce(v_row ->> 'entity_id', ''),
      'applicant', coalesce(v_row ->> 'applicant', ''),
      'amount', coalesce(v_row ->> 'amount', v_row ->> 'total', ''),
      'approval_step', v_step_number,
      'approval_role_key', v_role_key,
      'approval_role_label', v_role_label,
      'assignment_generation', v_generation,
      'app_url', 'https://finance.suiyuecare.com/'
    ),
    v_environment,
    v_tenant_id,
    now(),
    20
  )
  on conflict (id) do nothing;

  get diagnostics v_inserted_count = row_count;
  if v_inserted_count = 0 and not exists (
    select 1
    from public.notification_delivery_events existing
    where existing.id = v_event_id
      and existing.event_type = 'approval_task_assigned'
      and existing.tenant_id = v_tenant_id
      and existing.data_environment = v_environment
      and existing.request_id = v_source_no
      and existing.payload ->> 'source_table' = tg_table_name
      and existing.payload ->> 'source_id' = v_source_id
      and existing.payload ->> 'source_group_id' = v_source_group_id
      and existing.payload ->> 'source_no' = v_source_no
      and existing.payload ->> 'recipient_finance_user_id' = v_recipient_id
      and existing.payload -> 'recipient_emails' = jsonb_build_array(v_recipient_email)
  ) then
    raise exception using
      errcode = 'PNA01',
      message = format(
        'Reserved approval notification id collision for %s',
        v_event_id
      ),
      hint = 'Do not retry the business action until the conflicting event has been investigated.';
  end if;

  update private.approval_notification_assignment_state
  set notification_event_id = v_event_id,
      updated_at = now()
  where tenant_id = v_tenant_id
    and data_environment = v_environment
    and source_table = tg_table_name
    and source_group_id = v_source_group_id
    and assignment_generation = v_generation;

  begin
    perform private.finance_wake_notification_worker();
  exception
    when others then
      raise warning 'Approval email queued but worker wake failed: %', sqlerrm;
  end;

  return new;
exception
  when sqlstate 'PNA01' then
    -- A deterministic id collision is a security incident. Never let the
    -- trigger's best-effort fallback hide it or silently lose the email.
    raise;
  when others then
    raise warning 'Approval email enqueue skipped for %.%: %', tg_table_name, coalesce(v_source_id, '?'), sqlerrm;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_guard_bank_fee_single_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_should_check boolean := false;
  v_accounting_lines jsonb;
begin
  if tg_op = 'INSERT' then
    v_should_check := true;
  else
    v_should_check :=
      (new.form_payload -> 'accountingLines')
        is distinct from (old.form_payload -> 'accountingLines')
      or (
        new.status = 'completed'
        and old.status is distinct from 'completed'
      );
  end if;

  if not v_should_check then
    return new;
  end if;

  v_accounting_lines := coalesce(
    new.form_payload -> 'accountingLines',
    '[]'::jsonb
  );

  if pg_catalog.jsonb_typeof(v_accounting_lines) <> 'array' then
    return new;
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(v_accounting_lines)
      accounting_line(item)
    where pg_catalog.lower(
            coalesce(accounting_line.item ->> 'systemFee', 'false')
          ) in ('true', '1', 'yes')
       or (
         pg_catalog.lower(
           coalesce(accounting_line.item ->> 'locked', 'false')
         ) in ('true', '1', 'yes')
         and coalesce(accounting_line.item ->> 'description', '') =
           '銀行手續費（己方支出，免憑證）'
       )
  ) then
    raise exception
      '會計明細不可包含系統銀行手續費；手續費只由 bank_fee_amount 入帳'
      using errcode = '23514';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.finance_expense_correction_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_allowed boolean;
begin
  select exists(select 1 from private.expense_accounting_corrections_v1 c
    where c.tenant_id=old.tenant_id and c.data_environment=old.data_environment and c.request_id=old.id
      and c.id::text=coalesce(current_setting('app.finance_correction_write_id',true),'')
      and c.writing_transaction=pg_current_xact_id()::text) into v_allowed;
  if v_allowed then return new; end if;
  if (new.form_payload->'accountingCorrection') is distinct from (old.form_payload->'accountingCorrection')
    or (new.form_payload->'correctionCashEvents') is distinct from (old.form_payload->'correctionCashEvents')
    or ((old.form_payload ? 'correctionCashEvents') and (new.form_payload->'cashAmount') is distinct from (old.form_payload->'cashAmount')) then
    raise exception '金額更正與差額現金紀錄只能透過更正流程修改' using errcode='42501';
  end if;
  if exists(select 1 from private.expense_accounting_corrections_v1 c where c.tenant_id=old.tenant_id
    and c.data_environment=old.data_environment and c.request_id=old.id and c.status in ('pending_review','pending_cash'))
    and (to_jsonb(new)-'updated_at') is distinct from (to_jsonb(old)-'updated_at') then
    raise exception '此單有尚未完成的金額更正／差額處理，不能簽核或入帳' using errcode='55000',detail='ACCOUNTING_CORRECTION_PENDING';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_expense_guard_returned_middle_step()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old_active_index integer;
  v_old_step jsonb;
  v_old_role text;
  v_old_log jsonb;
  v_candidate jsonb;
  v_candidate_log jsonb;
  v_old_log_length integer;
  v_log_index integer;
  v_prefix_matches boolean;
  v_history_preserved boolean := false;
  v_old_add_sign_count bigint;
  v_new_add_sign_count bigint;
  v_old_assigned_count bigint;
  v_new_assigned_count bigint;
  v_old_add_sign_field_count bigint;
  v_new_add_sign_field_count bigint;
begin
  if coalesce(
       pg_catalog.current_setting(
         'app.finance_expense_write_context',
         true
       ),
       ''
     ) <> 'active_step'
     or old.steps is not distinct from new.steps then
    return new;
  end if;

  v_old_active_index := private.finance_income_active_step_index(old.steps);
  if v_old_active_index is null then
    return new;
  end if;

  v_old_step := old.steps -> v_old_active_index;
  v_old_role := private.finance_income_step_role(v_old_step);
  if v_old_role = 'applicant_revision'
     or v_old_role in (
       'accountant',
       'accountant_final',
       'admin_director',
       'ceo'
     ) then
    return new;
  end if;

  v_old_log := case
    when pg_catalog.jsonb_typeof(v_old_step -> 'actionLog') = 'array'
      then v_old_step -> 'actionLog'
    else '[]'::jsonb
  end;

  if not exists (
    select 1
    from pg_catalog.jsonb_array_elements(v_old_log) action_entry
    where coalesce(action_entry ->> 'action', '') = '退回上一關'
       or pg_catalog.lower(
            pg_catalog.btrim(coalesce(action_entry ->> 'action', ''))
          ) in (
            'return',
            'returned',
            'return_previous',
            'return previous'
          )
  ) then
    return new;
  end if;

  -- A returned step may shift when it is returned to the applicant. Locate
  -- the same logical step in NEW and require the complete old action history
  -- to remain an unchanged prefix. This prevents truncating the return marker
  -- to bypass the restricted supplement mode.
  v_old_log_length := pg_catalog.jsonb_array_length(v_old_log);
  for v_candidate in
    select workflow_step
    from pg_catalog.jsonb_array_elements(
      case
        when pg_catalog.jsonb_typeof(new.steps) = 'array'
          then new.steps
        else '[]'::jsonb
      end
    ) workflow_step
  loop
    if private.finance_income_step_role(v_candidate) = v_old_role
       and coalesce(
             private.finance_income_step_user_id(v_candidate),
             ''
           ) = coalesce(
             private.finance_income_step_user_id(v_old_step),
             ''
           )
       and pg_catalog.lower(coalesce(v_candidate ->> 'email', '')) =
           pg_catalog.lower(coalesce(v_old_step ->> 'email', ''))
       and coalesce(v_candidate ->> 'r', '') =
           coalesce(v_old_step ->> 'r', '') then
      v_candidate_log := case
        when pg_catalog.jsonb_typeof(v_candidate -> 'actionLog') = 'array'
          then v_candidate -> 'actionLog'
        else '[]'::jsonb
      end;
      v_prefix_matches :=
        pg_catalog.jsonb_array_length(v_candidate_log) >=
          v_old_log_length;

      if v_prefix_matches and v_old_log_length > 0 then
        for v_log_index in 0..v_old_log_length - 1 loop
          if v_candidate_log -> v_log_index is distinct from
               v_old_log -> v_log_index then
            v_prefix_matches := false;
            exit;
          end if;
        end loop;
      end if;

      if v_prefix_matches then
        v_history_preserved := true;
        exit;
      end if;
    end if;
  end loop;

  if not v_history_preserved then
    raise exception '被退回的中間關卡不可改寫或刪除原有退回紀錄'
      using errcode = '42501';
  end if;

  select pg_catalog.count(*)
    into v_old_add_sign_count
  from pg_catalog.jsonb_array_elements(old.steps) workflow_step
  cross join lateral pg_catalog.jsonb_array_elements(
    case
      when pg_catalog.jsonb_typeof(workflow_step -> 'actionLog') = 'array'
        then workflow_step -> 'actionLog'
      else '[]'::jsonb
    end
  ) action_entry
  where pg_catalog.lower(
          pg_catalog.btrim(coalesce(action_entry ->> 'action', ''))
        ) ~ '(加[[:space:]]*簽|add[_ -]?sign|counter[_ -]?sign|co[_ -]?sign)';

  select pg_catalog.count(*)
    into v_new_add_sign_count
  from pg_catalog.jsonb_array_elements(new.steps) workflow_step
  cross join lateral pg_catalog.jsonb_array_elements(
    case
      when pg_catalog.jsonb_typeof(workflow_step -> 'actionLog') = 'array'
        then workflow_step -> 'actionLog'
      else '[]'::jsonb
    end
  ) action_entry
  where pg_catalog.lower(
          pg_catalog.btrim(coalesce(action_entry ->> 'action', ''))
        ) ~ '(加[[:space:]]*簽|add[_ -]?sign|counter[_ -]?sign|co[_ -]?sign)';

  select pg_catalog.count(*)
    into v_old_assigned_count
  from pg_catalog.jsonb_array_elements(old.steps) workflow_step
  where private.finance_income_step_role(workflow_step) = 'assigned_user'
     or pg_catalog.lower(coalesce(workflow_step ->> 'status', '')) =
          'pending_countersign'
     or coalesce(workflow_step ->> 'r', '') ~ '加[[:space:]]*簽';

  select pg_catalog.count(*)
    into v_new_assigned_count
  from pg_catalog.jsonb_array_elements(new.steps) workflow_step
  where private.finance_income_step_role(workflow_step) = 'assigned_user'
     or pg_catalog.lower(coalesce(workflow_step ->> 'status', '')) =
          'pending_countersign'
     or coalesce(workflow_step ->> 'r', '') ~ '加[[:space:]]*簽';

  select pg_catalog.count(*)
    into v_old_add_sign_field_count
  from pg_catalog.jsonb_array_elements(old.steps) workflow_step
  cross join lateral pg_catalog.jsonb_each(workflow_step) step_field
  where pg_catalog.lower(step_field.key)
    ~ '(add[_ -]?sign|counter[_ -]?sign|co[_ -]?sign)';

  select pg_catalog.count(*)
    into v_new_add_sign_field_count
  from pg_catalog.jsonb_array_elements(new.steps) workflow_step
  cross join lateral pg_catalog.jsonb_each(workflow_step) step_field
  where pg_catalog.lower(step_field.key)
    ~ '(add[_ -]?sign|counter[_ -]?sign|co[_ -]?sign)';

  if v_new_add_sign_count > v_old_add_sign_count
     or v_new_assigned_count > v_old_assigned_count
     or v_new_add_sign_field_count > v_old_add_sign_field_count then
    raise exception '被退回的一般中間關卡只能補件、退回或不通過，不可新增加簽'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.prevent_invalid_expense_accounting_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  cash_write boolean;
  final_posting_write boolean;
begin
  if coalesce(new.data_environment, 'production') <> 'production' then
    return new;
  end if;

  if new.voided_at is not null then
    return new;
  end if;

  if old.status = 'completed'
     and coalesce(new.status, '') <> 'completed'
     and (old.voucher_id is not null or old.ledger_posted_at is not null or old.posting_locked_at is not null) then
    raise exception '會計狀態回退被擋：申請單 % 已完成入帳，不可直接退回未完成狀態；請建立沖銷傳票。',
      coalesce(new.no, new.id)
      using errcode = '23514';
  end if;

  cash_write := old.cash_posted_at is null and new.cash_posted_at is not null;
  if cash_write
     and not private.finance_steps_role_approved(new.steps, array['cashier']) then
    raise exception '付款狀態被擋：申請單 % 尚未完成出納關卡，不可寫入付款時間。',
      coalesce(new.no, new.id)
      using errcode = '23514';
  end if;

  final_posting_write :=
    (old.ledger_posted_at is null and new.ledger_posted_at is not null)
    or (old.posting_locked_at is null and new.posting_locked_at is not null)
    or (old.voucher_id is distinct from new.voucher_id and new.voucher_id is not null)
    or (coalesce(old.status, '') <> 'completed' and coalesce(new.status, '') = 'completed');

  if final_posting_write and private.finance_unapproved_step_count(new.steps) > 0 then
    raise exception '會計入帳被擋：申請單 % 尚有未完成簽核，不可寫入傳票或完成入帳。',
      coalesce(new.no, new.id)
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_preserve_human_accounting_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old_lines jsonb := coalesce(old.form_payload -> 'accountingLines', '[]'::jsonb);
  v_new_lines jsonb := new.form_payload -> 'accountingLines';
  v_merged_lines jsonb;
  v_write_context text := coalesce(
    pg_catalog.current_setting('app.finance_expense_write_context', true),
    ''
  );
begin
  if tg_op <> 'UPDATE'
     or pg_catalog.jsonb_typeof(v_old_lines) <> 'array'
     or not exists (
       select 1
       from pg_catalog.jsonb_array_elements(v_old_lines) line_item(value)
       where private.finance_accounting_line_is_human(line_item.value)
     ) then
    return new;
  end if;

  if pg_catalog.jsonb_typeof(v_new_lines) = 'array' then
    v_merged_lines := private.finance_merge_human_accounting_lines(
      v_old_lines,
      v_new_lines
    );
  elsif v_write_context = 'active_step' then
    v_merged_lines := v_old_lines;
  else
    -- A legitimate new-evidence stage (for example procurement actual
    -- receipts) may intentionally rebuild accounting lines. The old values
    -- remain available in the request version/audit trail.
    return new;
  end if;

  if v_merged_lines is distinct from v_new_lines then
    new.form_payload := pg_catalog.jsonb_set(
      coalesce(new.form_payload, '{}'::jsonb),
      '{accountingLines}',
      v_merged_lines,
      true
    ) || pg_catalog.jsonb_build_object(
      'accountingLinePolicy', 'human_override_authoritative_v1',
      'accountingLinesPreservedForReview', true,
      'accountingLinesPreservedAt', pg_catalog.now()
    );
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(v_merged_lines) line_item(value)
    where private.finance_accounting_line_is_human(line_item.value)
      and (
        coalesce((line_item.value ->> 'netAmount')::numeric, 0) < 0
        or coalesce((line_item.value ->> 'taxAmount')::numeric, 0) < 0
        or coalesce((line_item.value ->> 'grossAmount')::numeric, 0) < 0
        or coalesce((line_item.value ->> 'netAmount')::numeric, 0)
           + coalesce((line_item.value ->> 'taxAmount')::numeric, 0)
           <> coalesce((line_item.value ->> 'grossAmount')::numeric, 0)
        or coalesce(line_item.value ->> 'debitAccount', '') = ''
        or coalesce(line_item.value ->> 'creditAccount', '') = ''
      )
  ) then
    raise exception '人工覆核的會計明細金額或借貸科目不完整，已停止保存'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_utility_expense_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_posting boolean:=false;
begin
  if tg_op='UPDATE' then
    v_posting:=(old.ledger_posted_at is null and new.ledger_posted_at is not null)
      or (old.posting_locked_at is null and new.posting_locked_at is not null);
    if new.form_payload->'accountingLines' is not distinct from old.form_payload->'accountingLines' and not v_posting then
      return new;
    end if;
  end if;
  perform private.finance_assert_utility_lines_v1(new.form_payload->'accountingLines');
  return new;
end;
$function$
